  if (!isMounted()) {
    on(THEME_CHANGED_EVENT, onThemeChanged);
    state.set(
      isPageReload()
      && getStorageValue<StorageValue>(COMPONENT_NAME)
      || retrieveLaunchParams().themeParams,
    );
    isMounted.set(true);
  }
});

